import fs from "node:fs"
import { expect } from "@playwright/test"

// Demo passwords generated by backend/tests/e2e_server.py when the suite starts.
export const creds = () => JSON.parse(fs.readFileSync("e2e/.creds.json", "utf8"))

export async function login(page, who, password) {
  await page.goto("/login")
  await page.getByLabel("Username or email").fill(who)
  await page.getByLabel("Password").fill(password)
  await page.getByRole("button", { name: "Sign in" }).click()
}

export const loginStaff = (page, email = "creator@globx.co.in") => login(page, email, creds()[email]).then(() => expect(page).toHaveURL(/\/admin/))
export const loginCandidate = (page, user) => login(page, user, creds().candidate)

export const shot = (page, name) => page.screenshot({ path: `test-results/screens/${name}.png`, fullPage: true })

// Opens a proctored exam as a candidate and returns once the exam screen is showing.
export async function startProctoredExam(page, user, examTitle = "GLOBX Full-Stack Screening (Sample)", password = creds().candidate, expectRunner = true) {
  await login(page, user, password)
  await page.getByRole("heading", { name: "Your exams" }).waitFor()
  // dev-server test hook: pin the face count to exactly one. The fake camera is an animated test picture, so the real
  // detector would flicker on it. Set it on the page that is already open and on any later reload.
  await page.evaluate(() => { window.__faceCount = 1 })
  await page.addInitScript(() => { window.__faceCount = 1 })
  const card = page.locator("div[data-slot=card]").filter({ hasText: examTitle })
  await card.getByRole("link", { name: /Start|Resume/ }).click()
  await page.getByRole("button", { name: "Enable camera" }).click()
  await expect(page.getByTestId("face-status")).toHaveText("1 face detected", { timeout: 15_000 })
  const share = page.getByRole("button", { name: "Share my screen" })  // exams that ask for the whole screen
  if (await share.count()) { await share.click(); await expect(page.getByTestId("screen-status")).toBeVisible() }
  await page.getByLabel(/I understand and agree/).click()
  await page.getByRole("button", { name: "Start exam" }).click()
  await expect(page).toHaveURL(/\/exam\/attempt\//)
  if (expectRunner) await expect(page.getByText("Proctoring on")).toBeVisible()
}

// A brand-new candidate on the sample exam, made through the participants API (the way an admin would).
export async function newParticipant(request, name) {
  const email = "recruiter@globx.co.in"
  const auth = await (await request.post("/api/v1/auth/login", { data: { email, password: creds()[email] } })).json()
  const headers = { Authorization: "Bearer " + auth.access_token }
  const tests = await (await request.get("/api/v1/tests", { headers })).json()
  const exam = tests.find((t) => t.title.startsWith("GLOBX Full-Stack"))
  const out = await (await request.post(`/api/v1/tests/${exam.id}/participants`, { headers, data: { names: [name] } })).json()
  return out.participants[0]  // { username, password, ... }
}

// Calls the API as a staff member, the way a script would, to prepare data quickly. Fails the test on any error.
export async function staffRequest(request, email = "creator@globx.co.in") {
  const auth = await (await request.post("/api/v1/auth/login", { data: { email, password: creds()[email] } })).json()
  const headers = { Authorization: "Bearer " + auth.access_token }
  const call = async (method, path, data) => {
    const r = await request[method](`/api/v1${path}`, { headers, data })
    expect(r.ok(), `${method} ${path}: ${await r.text()}`).toBeTruthy()
    return r.json()
  }
  // `send` returns the raw response, for checking that the server refuses something
  return { get: (p) => call("get", p), post: (p, d) => call("post", p, d), send: (method, path, data) => request[method](`/api/v1${path}`, { headers, data }) }
}

// A second browser window with its own login and a (fake) camera: the candidate, while the admin watches in the first.
export const BASE_URL = process.env.E2E_BASE_URL || "http://localhost:5174"
export const candidateWindow = (browser) => browser.newContext({ baseURL: BASE_URL, ignoreHTTPSErrors: true, permissions: ["camera", "microphone"] }).then((ctx) => ctx.newPage().then((page) => ({ ctx, page })))
